package com.supermarkettracker.infrastructure.persistence.adapter;
import com.supermarkettracker.domain.model.*; import com.supermarkettracker.domain.model.valueobject.Identificador; import com.supermarkettracker.domain.repository.VendaRepository; import com.supermarkettracker.infrastructure.persistence.mapper.VendaPersistenceMapper; import com.supermarkettracker.infrastructure.persistence.repository.*; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class VendaRepositoryJpaAdapter implements VendaRepository { private final VendaJpaRepository vendas; private final ItemVendaJpaRepository itens; private final VendaPersistenceMapper mapper; public VendaRepositoryJpaAdapter(VendaJpaRepository v,ItemVendaJpaRepository i,VendaPersistenceMapper m){vendas=v;itens=i;mapper=m;} public Venda salvar(Venda x){return mapper.toDomain(vendas.save(mapper.toEntity(x)));} public Optional<Venda> buscarPorId(Identificador id){return vendas.findById(id.valor()).map(mapper::toDomain);} public ItemVenda salvarItem(ItemVenda x){return mapper.toDomain(itens.save(mapper.toEntity(x)));} public List<ItemVenda> listarItens(Identificador vendaId){return itens.findByVendaIdOrderByNumeroAsc(vendaId.valor()).stream().map(mapper::toDomain).toList();} }
